class Solution {
    public List<List<String>> displayTable(List<List<String>> orders) {
        TreeMap<Integer, List<String>> tables = new TreeMap<>();
        Set<String> items = new HashSet<>();
        for (List<String> o : orders) {
            int table = Integer.parseInt(o.get(1));
            String foodItem = o.get(2);
            tables.computeIfAbsent(table, k -> new ArrayList<>()).add(foodItem);
            items.add(foodItem);
        }
        List<String> sortedItems = new ArrayList<>(items);
        Collections.sort(sortedItems);
        List<List<String>> ans = new ArrayList<>();
        List<String> header = new ArrayList<>();
        header.add("Table");
        header.addAll(sortedItems);
        ans.add(header);
        for (Map.Entry<Integer, List<String>> entry : tables.entrySet()) {
            Map<String, Integer> cnt = new HashMap<>();
            for (String item : entry.getValue()) {
                cnt.merge(item, 1, Integer::sum);
            }
            List<String> row = new ArrayList<>();
            row.add(String.valueOf(entry.getKey()));
            for (String item : sortedItems) {
                row.add(String.valueOf(cnt.getOrDefault(item, 0)));
            }
            ans.add(row);
        }
        return ans;
    }
}

class Solution {
public:
    vector<vector<string>> displayTable(vector<vector<string>>& orders) {
        map<int, vector<string>> tables;
        set<string> sortedItems;
        for (auto& o : orders) {
            int table = stoi(o[1]);
            string foodItem = o[2];
            tables[table].push_back(foodItem);
            sortedItems.insert(foodItem);
        }
        vector<vector<string>> ans;
        vector<string> header = {"Table"};
        header.insert(header.end(), sortedItems.begin(), sortedItems.end());
        ans.push_back(header);
        for (auto& [table, items] : tables) {
            unordered_map<string, int> cnt;
            for (string& item : items) {
                cnt[item]++;
            }
            vector<string> row;
            row.push_back(to_string(table));
            for (const string& item : sortedItems) {
                row.push_back(to_string(cnt[item]));
            }
            ans.push_back(row);
        }
        return ans;
    }
};

func displayTable(orders [][]string) [][]string {
	tables := make(map[int]map[string]int)
	items := make(map[string]bool)
	for _, order := range orders {
		table, _ := strconv.Atoi(order[1])
		foodItem := order[2]
		if tables[table] == nil {
			tables[table] = make(map[string]int)
		}
		tables[table][foodItem]++
		items[foodItem] = true
	}
	sortedItems := make([]string, 0, len(items))
	for item := range items {
		sortedItems = append(sortedItems, item)
	}
	sort.Strings(sortedItems)
	ans := [][]string{}
	header := append([]string{"Table"}, sortedItems...)
	ans = append(ans, header)
	tableNums := make([]int, 0, len(tables))
	for table := range tables {
		tableNums = append(tableNums, table)
	}
	sort.Ints(tableNums)
	for _, table := range tableNums {
		row := []string{strconv.Itoa(table)}
		for _, item := range sortedItems {
			count := tables[table][item]
			row = append(row, strconv.Itoa(count))
		}
		ans = append(ans, row)
	}
	return ans
}

function displayTable(orders: string[][]): string[][] {
    const tables: Record<number, Record<string, number>> = {};
    const items: Set<string> = new Set();
    for (const [_, table, foodItem] of orders) {
        const t = +table;
        if (!tables[t]) {
            tables[t] = {};
        }
        if (!tables[t][foodItem]) {
            tables[t][foodItem] = 0;
        }
        tables[t][foodItem]++;
        items.add(foodItem);
    }
    const sortedItems = Array.from(items).sort();
    const ans: string[][] = [];
    const header: string[] = ['Table', ...sortedItems];
    ans.push(header);
    const sortedTableNumbers = Object.keys(tables)
        .map(Number)
        .sort((a, b) => a - b);
    for (const table of sortedTableNumbers) {
        const row: string[] = [table.toString()];
        for (const item of sortedItems) {
            row.push((tables[table][item] || 0).toString());
        }
        ans.push(row);
    }
    return ans;
}

class Solution {
public:
    vector<vector<string>> displayTable(vector<vector<string>>& orders) {
        unordered_set<string> food;
        unordered_map<int, unordered_map<string, int>> tables;
        for (int i = 0; i < orders.size(); i++) {
            food.insert(orders[i][2]);
            tables[stoi(orders[i][1])][orders[i][2]] += 1;
        }

        vector<string> food_list;
        for (auto cur_food : food) {
            food_list.push_back(cur_food);
        }
        sort(food_list.begin(), food_list.end());

        vector<int> id_list;
        for (auto cur_id : tables) {
            id_list.push_back(cur_id.first);
        }
        sort(id_list.begin(), id_list.end());

        vector<vector<string>> ans;
        vector<string> header;
        header.push_back("Table");
        for (int i = 0; i < food_list.size(); i++) {
            header.push_back(food_list[i]);
        }
        ans.push_back(header);
        for (int i = 0; i < id_list.size(); i++) {
            vector<string> row;
            row.push_back(to_string(id_list[i]));
            unordered_map<string, int> cur_map = tables[id_list[i]];
            for (int j = 0; j < food_list.size(); j++) {
                row.push_back(to_string(cur_map[food_list[j]]));
            }
            ans.push_back(row);
        }
        return ans;
    }
};

class Solution {
    public List<List<String>> displayTable(List<List<String>> orders) {
        Set<String> food = new HashSet<String>();
        Map<Integer, Map<String, Integer>> tables = new HashMap<Integer, Map<String, Integer>>();
        for (List<String> cur_order : orders) {
            food.add(cur_order.get(2));
            int cur_id = Integer.parseInt(cur_order.get(1));
            Map<String, Integer> cur_map = tables.getOrDefault(cur_id, new HashMap<String, Integer>());
            cur_map.put(cur_order.get(2), cur_map.getOrDefault(cur_order.get(2), 0) + 1);
            tables.put(cur_id, cur_map);
        }

        List<String> food_list = new ArrayList<String>();
        for (String cur_food : food) {
            food_list.add(cur_food);
        }
        Collections.sort(food_list);

        List<Integer> id_list = new ArrayList<Integer>();
        for (int id : tables.keySet()) {
            id_list.add(id);
        }
        Collections.sort(id_list);

        List<List<String>> ans = new ArrayList<List<String>>();
        List<String> header = new ArrayList<String>();
        header.add("Table");
        for (String cur_food : food_list) {
            header.add(cur_food);
        }
        ans.add(header);
        for (int cur_id : id_list) {
            List<String> row = new ArrayList<String>();
            row.add(Integer.toString(cur_id));
            Map<String, Integer> cur_map = tables.get(cur_id);
            for (String cur_food : food_list) {
                row.add(Integer.toString(cur_map.getOrDefault(cur_food, 0)));
            }
            ans.add(row);
        }
        return ans;
    }
}
